-- Repair hosted schema/history drift: Reference Visual authority was recorded
-- as applied while the shared asset-kind constraints omitted its image kind.
alter table tongs.assets drop constraint assets_asset_kind_check,add constraint assets_asset_kind_check check(asset_kind in('thumbnail_image','thumbnail_composite','image_map_json','image_map_candidate_image','broll_candidate_video','broll_candidate_poster','reference_clip_video','reference_clip_poster','reference_visual_image'));
alter table tongs.assets drop constraint assets_kind_shape_check,add constraint assets_kind_shape_check check((asset_kind in('thumbnail_image','thumbnail_composite','broll_candidate_poster','reference_clip_poster','reference_visual_image')and mime_type like'image/%')or(asset_kind='image_map_json'and mime_type='application/json'and prompt is null)or(asset_kind='image_map_candidate_image'and mime_type like'image/%'and prompt is not null)or(asset_kind in('broll_candidate_video','reference_clip_video')and mime_type like'video/%'));
